import{R as e,e as o,f as n,U as i}from"./chunks/framework.ywem4qy5.js";const u=JSON.parse('{"title":"Infusionsoft","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/infusionsoft.md","filePath":"integrations/crm/infusionsoft.md","lastUpdated":1775908585000}'),s={name:"integrations/crm/infusionsoft.md"};function r(a,t,l,c,f,h){return o(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="infusionsoft" tabindex="-1">Infusionsoft <a class="header-anchor" href="#infusionsoft" aria-label="Permalink to &quot;Infusionsoft&quot;">​</a></h1><p>Follow the below steps to connect to the Infusionsoft API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Infusionsoft as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-infusionsoft-api" tabindex="-1">Step 2. Connect to the Infusionsoft API <a class="header-anchor" href="#step-2-connect-to-the-infusionsoft-api" aria-label="Permalink to &quot;Step 2. Connect to the Infusionsoft API&quot;">​</a></h3><ol><li>Go to <a href="https://keys.developer.keap.com/accounts/login" target="_blank">Keap Developer Account</a> and login to your account.</li><li>Click on your profile dropdown on the top-right of the screen, and select <strong>Apps</strong>.</li><li>Click the <strong>+ New App</strong> button.</li><li>Fill out the required details, and be sure to enable APIs (small green icon button).</li><li>Click the <strong>Create</strong> button.</li><li>Copy the <strong>Key</strong> from Infusionsoft and paste in the <strong>Client ID</strong> field in Formie.</li><li>Copy the <strong>Secret</strong> from Infusionsoft and paste in the <strong>Client Secret</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to Infusionsoft, where you must approve Formie to access your Infusionsoft account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const p=e(s,[["render",r]]);export{u as __pageData,p as default};
